import "types"

contract CoinFlipFactory {
    author: "TON Coin Flip"
    version: "0.2.0"
    description: "Coin-flip platform: creates per-game escrow contracts, holds platform params"
    storage: FactoryStorage
    incomingMessages: AllowedFactoryMessage
}

type AllowedFactoryMessage =
    | CreateGame
    | SetFee
    | SetLimits
    | SetTreasury
    | SetPaused
    | SetGameCode
    | ProposeAdmin
    | ClaimAdmin
    | CancelAdminTransfer

fun assertSenderIsAdmin(senderAddress: address, admin: address) {
    assert (senderAddress == admin) throw Errors.NotAdmin;
}

fun onInternalMessage(in: InMessage) {
    val msg = lazy AllowedFactoryMessage.fromSlice(in.body);

    match (msg) {
        CreateGame => {
            var storage = FactoryStorage.load();
            assert (!storage.paused) throw Errors.GamePaused;
            assert (
                msg.stake >= storage.minStake && msg.stake <= storage.maxStake
            ) throw Errors.InvalidStake;
            assert (in.valueCoins >= msg.stake + CREATE_GAS_RESERVE) throw Errors.InsufficientValue;

            val gameId = storage.gamesCount;
            storage.gamesCount += 1;
            storage.save();

            val joinDeadline = (blockchain.now() + storage.joinTimeout) as uint32;
            // Snapshot of platform params: later admin changes must not affect this game
            val initialGameStorage: GameStorage = {
                config: GameConfig {
                    gameId,
                    factory: contract.getAddress(),
                    creator: in.senderAddress,
                    stake: msg.stake,
                    aSideHeads: msg.aSideHeads,
                    feeBps: storage.feeBps,
                    revealTimeout: storage.revealTimeout,
                    joinDeadline,
                    ext: GameConfigExt {
                        commitment: msg.commitment,
                        treasury: storage.treasury,
                    }.toCell(),
                }.toCell(),
                status: STATUS_CREATED,
                opponent: null,
                seedB: 0,
                revealDeadline: 0,
            };
            val gameDeploy: AutoDeployAddress = {
                stateInit: { code: storage.gameCode, data: initialGameStorage.toCell() },
            };

            val ev = createExternalLogMessage({
                dest: ExtOutLogBucket { topic: TOPIC_GAME_CREATED },
                body: EvGameCreated {
                    gameId,
                    game: gameDeploy.calculateAddress(),
                    creator: in.senderAddress,
                    stake: msg.stake,
                    joinDeadline,
                },
            });
            ev.send(SEND_MODE_REGULAR);

            // Forward the full remaining message value (stake escrow + gas buffer)
            val deployMsg = createMessage({
                bounce: BounceMode.NoBounce,
                dest: gameDeploy,
                value: 0,
            });
            deployMsg.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE);
        }

        SetFee => {
            var storage = FactoryStorage.load();
            assertSenderIsAdmin(in.senderAddress, storage.admin());
            assert (msg.feeBps <= MAX_FEE_BPS) throw Errors.FeeTooHigh;
            storage.feeBps = msg.feeBps;
            storage.save();
        }

        SetLimits => {
            var storage = FactoryStorage.load();
            assertSenderIsAdmin(in.senderAddress, storage.admin());
            assert (msg.minStake > 0 && msg.minStake <= msg.maxStake) throw Errors.InvalidLimits;
            assert (msg.joinTimeout > 0 && msg.revealTimeout > 0) throw Errors.InvalidLimits;
            storage.minStake = msg.minStake;
            storage.maxStake = msg.maxStake;
            storage.joinTimeout = msg.joinTimeout;
            storage.revealTimeout = msg.revealTimeout;
            storage.save();
        }

        SetTreasury => {
            var storage = FactoryStorage.load();
            assertSenderIsAdmin(in.senderAddress, storage.admin());
            storage.treasury = msg.treasury;
            storage.save();
        }

        SetPaused => {
            var storage = FactoryStorage.load();
            assertSenderIsAdmin(in.senderAddress, storage.admin());
            storage.paused = msg.paused;
            storage.save();
        }

        SetGameCode => {
            // Affects only games created after this point (constitution VIII)
            var storage = FactoryStorage.load();
            assertSenderIsAdmin(in.senderAddress, storage.admin());
            storage.gameCode = msg.code;
            storage.save();
        }

        ProposeAdmin => {
            // Step 1 of admin handover: the current admin nominates a successor
            // (e.g. a multisig). Control does not move until the successor claims.
            var storage = FactoryStorage.load();
            var gov = storage.gov.load();
            assert (in.senderAddress == gov.admin) throw Errors.NotAdmin;
            gov.pendingAdmin = msg.newAdmin;
            storage.gov = gov.toCell();
            storage.save();
        }

        ClaimAdmin => {
            // Step 2: only the nominated successor can accept, which proves the
            // new address is reachable and avoids handing control to a typo.
            var storage = FactoryStorage.load();
            var gov = storage.gov.load();
            assert (gov.pendingAdmin != null) throw Errors.NoPendingAdmin;
            assert (in.senderAddress == gov.pendingAdmin!) throw Errors.NotPendingAdmin;
            gov.admin = gov.pendingAdmin!;
            gov.pendingAdmin = null;
            storage.gov = gov.toCell();
            storage.save();
        }

        CancelAdminTransfer => {
            var storage = FactoryStorage.load();
            var gov = storage.gov.load();
            assert (in.senderAddress == gov.admin) throw Errors.NotAdmin;
            gov.pendingAdmin = null;
            storage.gov = gov.toCell();
            storage.save();
        }

        else => {
            // Plain TON transfers are accepted as a balance top-up
            assert (in.body.isEmpty()) throw Errors.InvalidMessage;
        }
    }
}

fun onBouncedMessage(_in: InMessageBounced) {}

get fun factoryData(): FactoryStorage {
    return FactoryStorage.load();
}

get fun gamesCount(): int {
    val storage = FactoryStorage.load();
    return storage.gamesCount;
}

get fun governance(): GovernanceData {
    val storage = FactoryStorage.load();
    val gov = storage.gov.load();
    return {
        admin: gov.admin,
        pendingAdmin: gov.pendingAdmin,
        treasury: storage.treasury,
    };
}

// Shared types for the TON Coin Flip platform.
// See docs/specification.md for the full protocol description.

enum Errors {
    NotAdmin = 100
    NotCreator = 101
    GamePaused = 102
    InvalidStake = 103
    InsufficientValue = 104
    FeeTooHigh = 105
    SelfPlayNotAllowed = 106
    WrongState = 107
    JoinDeadlinePassed = 108
    EscrowUnderfunded = 109
    CommitmentMismatch = 110
    RevealDeadlinePassed = 111
    RevealDeadlineNotReached = 112
    InvalidLimits = 113
    NotPendingAdmin = 114
    NoPendingAdmin = 115
    InvalidMessage = 0xFFFF
}

// Game lifecycle states (specification §5)
const STATUS_CREATED = 0
const STATUS_JOINED = 1
const STATUS_SETTLED = 2
const STATUS_TIMED_OUT = 3
const STATUS_CANCELLED = 4

// Fee is measured in basis points of the pot; the cap is hardcoded (constitution III, IX)
const BPS_DENOMINATOR = 10000
const MAX_FEE_BPS = 1000 // 10%

// Gas reserves: the part of the attached value that is NOT counted as stake.
// Anything above stake + reserve is refunded (join) or swept to the winner (settle).
const CREATE_GAS_RESERVE = ton("0.1")
const JOIN_GAS_RESERVE = ton("0.05")
const MIN_REFUND = ton("0.01")

// ---------------------------------------------------------------------------
// Storage
// ---------------------------------------------------------------------------

// Admin + a pending admin for two-step ownership transfer. Kept in a nested
// cell: a third address in the root storage would exceed the 1023-bit limit
// the moment pendingAdmin is set (see docs/architecture.md).
struct FactoryGov {
    admin: address
    pendingAdmin: address?
}

struct FactoryStorage {
    gov: Cell<FactoryGov>
    treasury: address
    feeBps: uint16
    minStake: coins
    maxStake: coins
    joinTimeout: uint32
    revealTimeout: uint32
    paused: bool
    gamesCount: uint64
    gameCode: cell
}

fun FactoryStorage.load(): FactoryStorage {
    return FactoryStorage.fromCell(contract.getData());
}

fun FactoryStorage.save(self) {
    contract.setData(self.toCell());
}

fun FactoryStorage.admin(self): address {
    return self.gov.load().admin;
}

// Flattened governance view for the `governance` get-method
struct GovernanceData {
    admin: address
    pendingAdmin: address?
    treasury: address
}

// Immutable per-game parameters, snapshotted from the factory at creation time
// (constitution VIII: later admin changes never affect an existing game).
// Split into two cells: three addresses + commitment exceed the 1023-bit cell limit.
struct GameConfigExt {
    commitment: uint256
    treasury: address
}

struct GameConfig {
    gameId: uint64
    factory: address
    creator: address
    stake: coins
    aSideHeads: bool
    feeBps: uint16
    revealTimeout: uint32
    joinDeadline: uint32
    ext: Cell<GameConfigExt>
}

struct GameStorage {
    config: Cell<GameConfig>
    status: uint8
    opponent: address?
    seedB: uint256
    revealDeadline: uint32
}

fun GameStorage.load(): GameStorage {
    return GameStorage.fromCell(contract.getData());
}

fun GameStorage.save(self) {
    contract.setData(self.toCell());
}

// Flattened read-only view returned by the `gameData` get-method
struct GameData {
    gameId: uint64
    factory: address
    creator: address
    stake: coins
    commitment: uint256
    aSideHeads: bool
    feeBps: uint16
    treasury: address
    joinDeadline: uint32
    status: uint8
    opponent: address?
    seedB: uint256
    revealDeadline: uint32
}

// ---------------------------------------------------------------------------
// Incoming messages (specification §6)
// ---------------------------------------------------------------------------

// Factory
struct (0xC0F10001) CreateGame {
    stake: coins
    commitment: uint256
    aSideHeads: bool
}

struct (0xC0F10002) SetFee {
    feeBps: uint16
}

struct (0xC0F10003) SetLimits {
    minStake: coins
    maxStake: coins
    joinTimeout: uint32
    revealTimeout: uint32
}

struct (0xC0F10004) SetTreasury {
    treasury: address
}

struct (0xC0F10005) SetPaused {
    paused: bool
}

struct (0xC0F10006) SetGameCode {
    code: cell
}

// Two-step admin transfer (safe for handing control to a multisig)
struct (0xC0F10007) ProposeAdmin {
    newAdmin: address
}

struct (0xC0F10008) ClaimAdmin {}

struct (0xC0F10009) CancelAdminTransfer {}

// Game
struct (0xC0F20001) JoinGame {
    seedB: uint256
}

struct (0xC0F20002) Reveal {
    secretA: uint256
}

struct (0xC0F20003) ClaimTimeout {}

struct (0xC0F20004) CancelGame {}

// ---------------------------------------------------------------------------
// Events (external-out log messages, indexed by ExtOutLogBucket topic)
// ---------------------------------------------------------------------------

const TOPIC_GAME_CREATED = 1
const TOPIC_GAME_JOINED = 2
const TOPIC_GAME_SETTLED = 3
const TOPIC_GAME_TIMED_OUT = 4
const TOPIC_GAME_CANCELLED = 5

struct (0xC0FE0001) EvGameCreated {
    gameId: uint64
    game: address
    creator: address
    stake: coins
    joinDeadline: uint32
}

struct (0xC0FE0002) EvGameJoined {
    gameId: uint64
    opponent: address
    seedB: uint256
    revealDeadline: uint32
}

struct (0xC0FE0003) EvGameSettled {
    gameId: uint64
    coinIsHeads: bool
    winner: address
    payout: coins
    fee: coins
}

struct (0xC0FE0004) EvGameTimedOut {
    gameId: uint64
    winner: address
    payout: coins
    fee: coins
}

struct (0xC0FE0005) EvGameCancelled {
    gameId: uint64
    refund: coins
}

// ---------------------------------------------------------------------------
// Provably-fair helpers (shared by contracts, tests and the off-chain verifier)
// ---------------------------------------------------------------------------

// commitment = SHA256(secretA as a 32-byte big-endian value)
fun calcCommitment(secretA: uint256): uint256 {
    return beginCell().storeUint(secretA, 256).endCell().beginParse().bitsHash();
}

// coin = LSB(secretA XOR seedB); true = heads (орел), false = tails (решка)
fun calcCoinIsHeads(secretA: uint256, seedB: uint256): bool {
    return ((secretA ^ seedB) & 1) == 1;
}

// fee = floor(pot * feeBps / 10000); the rounding dust stays in the winner payout
fun calcFee(pot: coins, feeBps: int): coins {
    return pot * feeBps / BPS_DENOMINATOR;
}
